    pub const fn case_id_column(&self) -> &'a arrow_array::FixedSizeBinaryArray {
        self.case_id_column
    }
    #[doc = concat!("Borrows the exact declared field for `", "case_id", "`.")]
    pub fn case_id_field(&self) -> &'a crate::FieldRef {
        &self.batch.schema_ref().fields()[0usize]
    }
